'use strict';
const V27Counts={phases:{DRAFT:'草稿',IN_PROGRESS:'进行中',REVIEW:'待复核',APPROVAL:'待审批',ADJUSTMENTS:'待调整生效',COMPLETED:'已完成',CANCELLED:'已取消'},findings:{MATCH:'一致',UNCOUNTED:'尚未清点',GAIN:'盘盈',LOSS:'盘亏',LOCATION:'货位差异',WEIGHT:'重量差异',STATUS:'状态差异',DUPLICATE:'重复登记',UNVERIFIED_MOVEMENT:'流转待核验',RECONCILED_MOVEMENT:'流转已核验',REMOVED_BY_FLOW:'正常业务流转移出',OFFSITE_PENDING:'已离场待正式出库'},
 locations(m,project,warehouse){return m.locations.filter(l=>l.active&&l.project_id===project&&l.warehouse_id===warehouse&&['FORMAL','TEMPORARY'].includes(l.map_usage)&&l.map_cell_code&&!l.map_parent_id);},
 async list(){return StocktakeList.list(false);},
 async create(){const [m,users]=await Promise.all([Business.load(),API.request('/users')]);Router.page('新建盘点任务',`<form id="v27-count-create" class="user-form"><div class="form-grid"><label>盘点类型<select name="task_type"><option value="MONTHLY">月度常规盘点</option><option value="ANNUAL">年度盘点</option><option value="SPECIAL">临时专项盘点</option></select></label><label>项目<select name="project_id">${Business.options(m.projects,null,'name')}</select></label><label>仓库<select name="warehouse_id">${Business.options(m.warehouses,null,'name')}</select></label><label>货位范围<select name="location_id"><option value="">全部正式货位与新生产捆包堆存区</option>${Business.options(this.locations(m,m.projects[0]?.id,m.warehouses[0]?.id),null,'code')}</select></label><label>盘点负责人<select name="assigned_to">${users.items.filter(u=>u.active&&u.role_code==='admin').map(u=>`<option data-no-i18n value="${u.id}" ${u.id===CurrentUser.id?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></label><label>计划截止时间<input name="cutoff_at" value="${new Date().toISOString()}" required></label></div><label>备注<textarea name="remark" maxlength="2000"></textarea></label><p class="v27-notice">开始盘点时冻结即时账面快照；不虚构回溯历史快照。后续正常业务继续运行。</p><p id="v27-count-create-error" class="error" role="alert"></p><button class="button primary">保存草稿</button></form>`);const form=$('v27-count-create'),sync=()=>{form.elements.location_id.innerHTML='<option value="">全部正式货位与新生产捆包堆存区</option>'+Business.options(this.locations(m,form.elements.project_id.value,form.elements.warehouse_id.value),null,'code');I18n.apply();};form.elements.project_id.onchange=()=>{form.elements.warehouse_id.innerHTML=Business.options(m.warehouses.filter(w=>w.project_id===form.elements.project_id.value),null,'name');sync();};form.elements.warehouse_id.onchange=sync;form.elements.project_id.onchange();$('v27-count-create').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));if(!body.location_id)delete body.location_id;const d=await API.request('/v27/stocktakes',{method:'POST',body});await Router.go('/stocktaking/'+d.id);}catch(err){$('v27-count-create-error').textContent=err.message;e.submitter.disabled=false;}};},
 async detail(id){const d=await API.request('/v27/stocktakes/'+id+'?'+new URLSearchParams(location.search)),r=d.report,independent=d.created_by!==CurrentUser.id&&!d.observations.some(o=>o.counted_by===CurrentUser.id),actions=[];
 if(Business.can('stocktake:write')){if(d.phase==='DRAFT')actions.push(['start','开始盘点']);if(d.phase==='IN_PROGRESS')actions.push(['submit-review','提交差异复核']);if(['DRAFT','IN_PROGRESS','REVIEW'].includes(d.phase))actions.push(['cancel','取消任务']);}
 if(Business.can('stocktake:review')){if(d.phase==='REVIEW')actions.push(['review','复核通过']);if(d.phase==='APPROVAL'&&Business.can('adjust:approve'))actions.push(['approve','审批通过']);if(['REVIEW','APPROVAL'].includes(d.phase))actions.push(['reject','驳回复盘']);if(d.phase==='ADJUSTMENTS')actions.push(['complete','完成并归档']);}
 Router.page('盘点任务 · '+d.code,`<p><span>任务状态</span>：${UI.status(d.phase,'count',this.phases[d.phase])} · <span>盘点类型</span>：${({MONTHLY:'月度常规盘点',ANNUAL:'年度盘点',SPECIAL:'临时专项盘点'})[d.task_type]||d.task_type}</p><p data-no-i18n>${esc(d.snapshot_at)}</p><p class="v27-notice">快照及已完成结果不可覆盖。重量仅汇总已知值，未检斤不按零处理；已装车与已离场状态单独核查。</p>${r.snapshot_pending?'<p>草稿尚未冻结快照</p>':`<div class="overview-ledger">${[['快照已知净重',r.opening_weight],['截止已知净重',r.closing_weight],['已知重量差异',r.difference]].map(([label,v])=>`<p>${label}<br><strong>${Tonnes.format(v)}</strong> <span>吨</span></p>`).join('')}</div><p>${r.unknown_opening||0} <span>捆快照重量未知</span> · ${r.unknown_closing||0} <span>捆截止重量未知</span></p>`}<div class="business-toolbar">${d.phase==='IN_PROGRESS'&&Business.can('stocktake:write')?'<button id="v27-record" class="button primary">录入实盘结果</button>':''}${actions.map(([action,label])=>`<button data-v27-count-action="${action}" class="button secondary">${label}</button>`).join('')}<button id="v27-count-export" class="button secondary">导出盘点档案</button><a class="button secondary" href="/stock-map?stocktake_id=${d.id}&amp;project_id=${d.project_id}&amp;warehouse_id=${d.warehouse_id}">查看范围地图</a></div><p id="v27-count-error" class="error" role="alert"></p><div class="business-table"><table><thead><tr><th>捆包编号</th><th>差异类型</th><th>快照净重（吨）</th><th>实盘毛重（吨）</th><th>实盘净重（吨）</th><th>实际货位</th><th>实际清点时间</th><th>差异原因</th><th>操作</th></tr></thead><tbody>${r.rows.map(row=>`<tr><td><a data-no-i18n href="/inventory/${encodeURIComponent(row.bundle_no)}">${esc(row.bundle_no)}</a></td><td>${this.findings[row.finding]||esc(row.finding)}${row.weight_mismatch&&row.finding!=='WEIGHT'?'<br><span>重量差异</span>':''}${row.location_mismatch&&row.finding!=='LOCATION'?'<br><span>货位差异</span>':''}</td><td>${Tonnes.format(row.opening)}</td><td>${Tonnes.format(row.actual_gross)}</td><td>${Tonnes.format(row.actual_weight)}</td><td data-no-i18n>${esc(row.actual_location||'—')}</td><td data-no-i18n>${esc(row.observed_at||row.counted_at||'—')}</td><td data-no-i18n>${esc(row.remark||'—')}</td><td>${d.phase==='IN_PROGRESS'&&Business.can('stocktake:write')?`<button data-v27-edit-count="${esc(row.bundle_no)}">录入或有据更正</button>`:''}${d.phase==='ADJUSTMENTS'&&independent&&Business.can('stocktake:review')&&(['GAIN','LOSS','WEIGHT','LOCATION','STATUS'].includes(row.finding))?`<button data-v27-resolve="${esc(row.bundle_no)}">差异处理</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="business-toolbar"><button id="v27-rows-prev" ${r.page===1?'disabled':''}>上一页</button><span>${r.page} / ${Math.max(1,Math.ceil(r.total_rows/r.page_size))}</span><button id="v27-rows-next" ${r.page*r.page_size>=r.total_rows?'disabled':''}>下一页</button></div><h2>差异处理与调整记录</h2>${d.resolutions.map(s=>`<p><span data-no-i18n>${esc(s.bundle_no)} · ${esc(s.adjustment_code||s.receipt_id||'—')}</span> · ${esc(Control.names[s.adjustment_status]||({ADJUSTMENT:'正式调整',INBOUND:'入库依据',VERIFIED:'原业务已核查'}[s.method])||s.method)} · <span data-no-i18n>${esc(s.reason)}</span>${s.adjustment_id?` <button data-v27-adjustment="${s.adjustment_id}">查看调整单</button>`:''}</p>`).join('')}<details><summary>盘点审批及历史</summary>${d.steps.map(s=>`<p><span data-no-i18n>${esc(s.occurred_at)} · ${esc(s.actor_name)}</span> · <span>${esc({DRAFT:'保存草稿',start:'开始盘点','submit-review':'提交差异复核',review:'复核通过',approve:'审批通过',reject:'驳回复盘',cancel:'取消任务',complete:'完成并归档'}[s.action]||'业务操作')}</span> · <span data-no-i18n>${esc(s.note)}</span></p>`).join('')}</details>`);
 for(const [button,step] of [['v27-rows-prev',-1],['v27-rows-next',1]])$(button).onclick=()=>Router.go('/stocktaking/'+id+'?rows_page='+(r.page+step));const run=async(action,note)=>{try{await API.request('/v27/stocktakes/'+id+'/'+action,{method:'POST',body:{version:d.version,note}});await this.detail(id);}catch(e){$('v27-count-error').textContent=e.message;throw e;}};
 for(const b of document.querySelectorAll('[data-v27-count-action]'))b.onclick=()=>this.reasonForm(b.textContent,note=>run(b.dataset.v27CountAction,note));if($('v27-record'))$('v27-record').onclick=()=>this.record(d,{});for(const b of document.querySelectorAll('[data-v27-edit-count]'))b.onclick=()=>this.record(d,r.rows.find(row=>row.bundle_no===b.dataset.v27EditCount));for(const b of document.querySelectorAll('[data-v27-resolve]'))b.onclick=()=>this.resolve(d,r.rows.find(row=>row.bundle_no===b.dataset.v27Resolve));for(const b of document.querySelectorAll('[data-v27-adjustment]'))b.onclick=()=>Control.adjustment(b.dataset.v27Adjustment);$('v27-count-export').onclick=async()=>{try{const out=await API.request('/v27/stocktakes/'+id+'/export',{binary:true}),url=URL.createObjectURL(out.blob),a=document.createElement('a');a.href=url;a.download=d.code+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){$('v27-count-error').textContent=e.message;}};
 },
 reasonForm(title,submit){dialog(title,'<form id="v27-reason-form" class="user-form"><label>操作依据<textarea name="reason" required minlength="5" maxlength="2000"></textarea></label><p id="v27-reason-error" class="error"></p><button class="button primary">确认提交</button></form>');$('v27-reason-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const value=e.target.elements.reason.value;await submit(value);$('dialog').close();}catch(err){$('v27-reason-error').textContent=err.message;e.submitter.disabled=false;}};},
 async record(d,row){const m=await Business.load();dialog('录入实盘结果',`<form id="v27-observation" class="user-form"><label>捆包编号<input name="bundle_no" required maxlength="512" value="${esc(row.bundle_no||'')}" ${row.observation_id?'readonly':''}></label><label>实存确认<select name="present"><option value="true">实物已找到</option><option value="false">实物未找到</option></select></label><label>实际货位<select name="actual_location_id">${Business.options(this.locations(m,d.project_id,d.warehouse_id),row.actual_location_id||row.closing_snapshot?.location_id||row.book_snapshot?.location_id,'code')}</select></label><label>实际业务状态<select name="actual_state">${[['UNKNOWN','待核实'],['AVAILABLE','未备货'],['RESERVED','备货锁定'],['LOADED','已装车'],['DEPARTED','已离场']].map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>实盘毛重（吨）<input name="actual_gross" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" value="${row.actual_gross==null?'':Tonnes.format(row.actual_gross)}"></label><p>未称重留空，不以零代表未知；净重按毛重减0.0025吨计算。</p><label>实际清点时间<input name="observed_at" required value="${new Date().toISOString()}"></label><label>差异或更正原因<textarea name="remark" maxlength="500" ${row.observation_id?'required':''}>${esc(row.remark||'')}</textarea></label><p id="v27-observation-error" class="error"></p><button class="button primary">保存清点进度</button></form>`);$('v27-observation').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(e.target));b.present=b.present==='true';if(!b.actual_gross)delete b.actual_gross;if(!b.present){b.actual_location_id=null;delete b.actual_gross;}if(row.observation_id)b.replaces_id=row.observation_id;await API.request('/v27/stocktakes/'+d.id+'/observations',{method:'POST',body:{version:d.version,entries:[b]}});$('dialog').close();await this.detail(d.id);}catch(err){$('v27-observation-error').textContent=err.message;e.submitter.disabled=false;}};},
 async resolve(d,row){const m=await Business.load(),findings=[row.finding,...(row.weight_mismatch?['WEIGHT']:[]),...(row.location_mismatch?['LOCATION']:[])].filter((v,i,a)=>a.indexOf(v)===i);dialog('差异处理',`<form id="v27-resolution" class="user-form"><p data-no-i18n>${esc(row.bundle_no)}</p><label>处理差异<select name="finding">${findings.map(f=>`<option value="${f}">${this.findings[f]}</option>`).join('')}</select></label><label>处理方式<select name="method"><option value="ADJUSTMENT">创建正式调整单</option><option value="INBOUND">关联已确认入库单</option><option value="VERIFIED">原业务流程核查完成</option><option value="CORRECTION">关联已生效冲销或更正</option></select></label><label>实际货位<select name="location_id">${Business.options(this.locations(m,d.project_id,d.warehouse_id),row.actual_location_id,'code')}</select></label><label>实测毛重（吨）<input name="gross_weight" inputmode="decimal" value="${row.actual_gross==null?'':Tonnes.format(row.actual_gross)}"></label><label>来源单据依据<input name="basis_document" maxlength="500"></label><label>生产批次<select name="batch_id">${Business.options(m.batches.filter(b=>b.project_id===d.project_id),null,'code')}</select></label><label>客户<select name="customer_id">${Business.options(m.customers.filter(c=>c.project_id===d.project_id),null,'name')}</select></label><label>已确认入库单内部编号<input name="receipt_id"></label><label>已生效更正单内部编号<input name="correction_id"></label><label>处理依据<textarea name="reason" required minlength="5" maxlength="2000"></textarea></label><p id="v27-resolution-error" class="error"></p><button class="button primary">生成处理记录</button></form>`);$('v27-resolution').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(e.target)),method=b.method,reason=b.reason;delete b.method;delete b.reason;for(const k of Object.keys(b))if(!b[k])delete b[k];await API.request('/v27/stocktakes/'+d.id+'/resolve',{method:'POST',body:{version:d.version,bundle_no:row.bundle_no,method,reason,details:b}});$('dialog').close();await this.detail(d.id);}catch(err){$('v27-resolution-error').textContent=err.message;e.submitter.disabled=false;}};}
};

Control.stocktakes=()=>Router.go('/stocktaking');
